/* 校園美食地圖 — static frontend.
 * Data: data/places.json + data/config.json (generated by scripts/export_static.py).
 * Ports FoodMapService.rank_nearby filtering/sorting, opening-hours logic and the
 * wheel from the Python app so the site needs no server (no cold start).
 */
(() => {
  "use strict";

  const $ = (sel) => document.querySelector(sel);
  const TIER_LABEL = { low: "低", medium: "普通", high: "高" };
  const WHEEL_COLORS = ["#FF6B6B", "#4ECDC4", "#FFE66D", "#A8E6CF", "#DDA0DD", "#87CEEB", "#F4A460", "#98D8C8", "#F7DC6F", "#BB8FCE"];
  const EARTH_R_KM = 6371.0;

  let CFG = null;
  let PLACES = [];
  let rows = []; // current filtered + ranked rows
  let selectedId = null;
  let tableSort = null; // {key, dir} when user clicked a header; null = sidebar order
  const selectedGroups = new Set();

  // ---------- helpers ----------
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const toRad = (d) => (d * Math.PI) / 180;

  function haversineKm(lat1, lon1, lat2, lon2) {
    const p1 = toRad(lat1), p2 = toRad(lat2);
    const dphi = p2 - p1, dl = toRad(lon2 - lon1);
    const a = Math.sin(dphi / 2) ** 2 + Math.cos(p1) * Math.cos(p2) * Math.sin(dl / 2) ** 2;
    return EARTH_R_KM * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(Math.max(0, 1 - a)));
  }

  function formatDistance(m) {
    return m >= 1000 ? `${(m / 1000).toFixed(1)} km` : `${m} 公尺`;
  }

  // ---------- opening hours (Asia/Taipei), mirrors foodmap/opening_hours.py ----------
  const taipeiFmt = new Intl.DateTimeFormat("en-US", {
    timeZone: "Asia/Taipei", weekday: "short", year: "numeric", month: "numeric", day: "numeric",
    hour: "numeric", minute: "numeric", hourCycle: "h23",
  });
  const WEEKDAY = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 }; // Google: 0 = Sunday

  function taipeiNow() {
    const parts = Object.fromEntries(taipeiFmt.formatToParts(new Date()).map((p) => [p.type, p.value]));
    const day = WEEKDAY[parts.weekday];
    const hour = Number(parts.hour) % 24;
    return {
      y: Number(parts.year), m: Number(parts.month), d: Number(parts.day),
      minutes: day * 1440 + hour * 60 + Number(parts.minute),
    };
  }

  const pointMinutes = (pt) => (Number(pt.day) || 0) * 1440 + (Number(pt.hour) || 0) * 60 + (Number(pt.minute) || 0);

  function openForPeriods(periods, now) {
    for (const period of periods) {
      if (!period || typeof period.open !== "object" || !period.open) continue;
      const o = pointMinutes(period.open);
      if (!period.close || typeof period.close !== "object") {
        if (now >= o) return true;
        continue;
      }
      const c = pointMinutes(period.close);
      if (c <= o) {
        if (now >= o || now < c) return true;
      } else if (o <= now && now < c) {
        return true;
      }
    }
    return false;
  }

  function isOpenNow(place, now) {
    if (place.status === "CLOSED_PERMANENTLY" || place.status === "CLOSED_TEMPORARILY") return false;
    const hours = place.hours;
    if (!hours || !Array.isArray(hours.periods)) return null;
    if (hours.periods.length === 0) return false;
    if (Array.isArray(hours.specialDays)) {
      const sp = hours.specialDays.find((e) => e && e.date && Number(e.date.year) === now.y && Number(e.date.month) === now.m && Number(e.date.day) === now.d);
      if (sp) {
        if (sp.closed === true) return false;
        if (Array.isArray(sp.exceptional_periods)) return openForPeriods(sp.exceptional_periods, now.minutes);
      }
    }
    return openForPeriods(hours.periods, now.minutes);
  }

  const openLabel = (v) => (v === true ? "營業中" : v === false ? "休息中" : "未知");
  const openClass = (v) => (v === true ? "open-yes" : v === false ? "open-no" : "open-unknown");

  // ---------- filters, mirrors FoodMapService.rank_nearby ----------
  function passesBudget(p, maxPriceLevel, maxSpend, includeUnknown) {
    if (maxPriceLevel == null && maxSpend == null) return true;
    if (p.avg_spend_ntd != null && maxSpend != null && p.avg_spend_ntd <= maxSpend) return true;
    if (p.price_level != null && maxPriceLevel != null && p.price_level <= maxPriceLevel) return true;
    return includeUnknown && p.avg_spend_ntd == null && p.price_level == null;
  }

  const matchesGroups = (groups, selected) => !selected.length || groups.some((g) => selected.includes(g));

  function readState() {
    const budget = $("#f-budget").checked;
    const groups = [...selectedGroups];
    if ($("#f-other").checked) groups.push(CFG.food_group_other);
    return {
      lat: Number($("#f-lat").value),
      lon: Number($("#f-lon").value),
      radius: Number($("#f-radius").value),
      minReviews: Math.max(0, Number($("#f-min-reviews").value) || 0),
      groups,
      maxPriceLevel: budget ? 1 : null,
      maxSpend: budget ? Number($("#f-max-spend").value) || 100 : null,
      includeUnknown: $("#f-unknown-price").checked,
      openOnly: $("#f-open-only").checked,
      sort: $("#f-sort").value,
      limit: Number($("#f-limit").value),
      q: $("#f-search").value.trim().toLowerCase(),
    };
  }

  const SORTERS = {
    composite: (a, b) => b.composite - a.composite,
    huang: (a, b) => b.huang - a.huang || a.distKm - b.distKm,
    rating: (a, b) => b.bayes - a.bayes || a.distKm - b.distKm,
    distance: (a, b) => a.distKm - b.distKm,
  };

  function rank(st) {
    const now = taipeiNow();
    const out = [];
    for (const p of PLACES) {
      if (p.reviews < st.minReviews) continue;
      if (!passesBudget(p, st.maxPriceLevel, st.maxSpend, st.includeUnknown)) continue;
      if (!matchesGroups(p.groups, st.groups)) continue;
      if (st.q && !p.name.toLowerCase().includes(st.q) && !p.groups.some((g) => g.includes(st.q))) continue;
      const distKm = haversineKm(st.lat, st.lon, p.lat, p.lon);
      if (distKm > st.radius) continue;
      const open = isOpenNow(p, now);
      if (st.openOnly && open !== true) continue;
      const distM = Math.round(distKm * 1000);
      out.push({ ...p, distKm, distM, distText: formatDistance(distM), open, composite: p.huang * Math.exp(-distKm / CFG.decay_km) });
    }
    out.sort(SORTERS[st.sort] || SORTERS.composite);
    return out.slice(0, st.limit);
  }

  // ---------- map ----------
  let map, layerGroup, centerMarker, radiusCircle;
  const markerById = new Map();

  function initMap() {
    map = L.map("map", { preferCanvas: true, zoomControl: true }).setView(CFG.center, 15);
    const tiles = CFG.tiles || {};
    L.tileLayer(tiles.url || "https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png", {
      maxZoom: tiles.max_zoom || 20,
      subdomains: tiles.subdomains || "abcd",
      attribution: tiles.attribution || '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> &copy; <a href="https://carto.com/attributions">CARTO</a>',
    }).addTo(map);
    layerGroup = L.layerGroup().addTo(map);
    radiusCircle = L.circle(CFG.center, { radius: 500, color: "#1a73e8", weight: 1, fillOpacity: 0.04, interactive: false }).addTo(map);
    centerMarker = L.marker(CFG.center, {
      draggable: true,
      zIndexOffset: 1000,
      icon: L.divIcon({ className: "", html: '<div class="center-pin"></div>', iconSize: [18, 18], iconAnchor: [9, 9] }),
      title: "中心點（可拖曳）",
    }).addTo(map);
    centerMarker.on("dragend", () => {
      const { lat, lng } = centerMarker.getLatLng();
      setCenter(lat, lng, "已改用拖曳的位置");
    });
  }

  function drawMap(st, fit) {
    layerGroup.clearLayers();
    markerById.clear();
    for (const r of rows) {
      const sel = r.id === selectedId;
      const m = L.circleMarker([r.lat, r.lon], {
        radius: sel ? 10 : 6,
        color: "#fff",
        weight: sel ? 2 : 1,
        fillColor: sel ? "#fbbc05" : "#ea4335",
        fillOpacity: 0.92,
      });
      m.bindTooltip(`<b>${esc(r.name)}</b><br>★ ${r.rating.toFixed(1)}（${r.reviews} 則）<br>${r.distText} · ${openLabel(r.open)}`, { className: "r-tip", direction: "top", offset: [0, -4] });
      m.on("click", () => selectRow(r.id, { scrollList: true }));
      m.addTo(layerGroup);
      markerById.set(r.id, m);
    }
    const sm = markerById.get(selectedId);
    if (sm) sm.bringToFront();
    centerMarker.setLatLng([st.lat, st.lon]);
    radiusCircle.setLatLng([st.lat, st.lon]).setRadius(st.radius * 1000);
    // Circle#getBounds is stale until redraw; compute from center + radius instead.
    if (fit) map.fitBounds(L.latLng(st.lat, st.lon).toBounds(st.radius * 2000), { padding: [10, 10], maxZoom: 16 });
  }

  // ---------- list ----------
  const TABLE_KEYS = {
    name: (r) => r.name,
    distance: (r) => r.distKm,
    open: (r) => (r.open === true ? 2 : r.open === null ? 1 : 0),
    rating: (r) => r.rating,
    reviews: (r) => r.reviews,
    huang: (r) => r.huang,
    composite: (r) => r.composite,
  };

  function tableRows() {
    if (!tableSort) return rows;
    const key = TABLE_KEYS[tableSort.key];
    const dir = tableSort.dir;
    return [...rows].sort((a, b) => {
      const va = key(a), vb = key(b);
      const c = typeof va === "string" ? va.localeCompare(vb, "zh-Hant") : va - vb;
      return dir * c;
    });
  }

  function drawTable() {
    const tbody = $("#rtable tbody");
    tbody.innerHTML = tableRows().map((r) => `
      <tr data-id="${esc(r.id)}"${r.id === selectedId ? ' class="selected"' : ""}>
        <td class="name">${esc(r.name)}</td>
        <td class="num">${r.distText}</td>
        <td class="${openClass(r.open)}">${openLabel(r.open)}</td>
        <td class="num">${r.rating.toFixed(1)}</td>
        <td class="num">${r.reviews.toLocaleString("zh-TW")}</td>
        <td>${esc(r.spend)}</td>
        <td class="groups">${esc(r.groups.join("、"))}</td>
        <td class="num">${r.huang.toFixed(2)}</td>
        <td class="num">${r.composite.toFixed(2)}</td>
        <td><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">📖 開啟</a></td>
      </tr>`).join("");
    document.querySelectorAll("#rtable th[data-sort]").forEach((th) => {
      if (tableSort && th.dataset.sort === tableSort.key) th.setAttribute("aria-sort", tableSort.dir > 0 ? "ascending" : "descending");
      else th.removeAttribute("aria-sort");
    });
    $("#empty").hidden = rows.length > 0;
    $("#rtable").hidden = rows.length === 0;
  }

  function drawFocus() {
    const r = rows.find((x) => x.id === selectedId);
    const box = $("#focus-card");
    if (!r) { box.innerHTML = ""; return; }
    box.innerHTML = `
      <div class="focus-card">
        <h3>${esc(r.name)}</h3>
        <p>Google 評分 <span class="star">★ ${r.rating.toFixed(1)}</span>（${r.reviews.toLocaleString("zh-TW")} 則評論）
          · <span class="${openClass(r.open)}">${openLabel(r.open)}</span> · 平均消費 ${esc(r.spend)} · 距離 ${r.distText}</p>
        <p>${esc(r.groups.join("、"))} · 黃氏星等 ${r.huang.toFixed(2)} · 貝氏 ${r.bayes.toFixed(2)} · 綜合分數 ${r.composite.toFixed(4)} · 星等分級 ${TIER_LABEL[r.tier] || r.tier}</p>
        <a class="btn btn-primary" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">在 Google Maps 查看評價與導航</a>
      </div>`;
  }

  function selectRow(id, { scrollList = false, pan = true } = {}) {
    selectedId = selectedId === id ? null : id;
    drawTable();
    drawFocus();
    drawMap(readState(), false);
    const r = rows.find((x) => x.id === selectedId);
    if (r && pan) map.setView([r.lat, r.lon], Math.max(map.getZoom(), 16), { animate: true });
    if (r && scrollList) {
      const tr = document.querySelector(`#rtable tr[data-id="${CSS.escape(r.id)}"]`);
      if (tr) tr.scrollIntoView({ block: "nearest", behavior: "smooth" });
    }
  }

  // ---------- wheel, mirrors foodmap/wheel.py + streamlit_app._wheel_candidate_df ----------
  let wheelItems = [];
  let rotation = 0;
  let spinning = false;
  let wheelSig = null;

  function wheelEligible(r) {
    if (CFG.wheel_excluded_name_keywords.some((k) => r.name.includes(k))) return false;
    if (!r.groups.length) return false;
    return !r.groups.some((g) => CFG.wheel_excluded_groups.includes(g));
  }

  function wheelCandidates(st) {
    let cands = rows.filter((r) => r.open !== false && wheelEligible(r));
    if (st.groups.length) {
      const wg = new Set([...st.groups, CFG.food_group_other]);
      cands = cands.filter((r) => r.groups.some((g) => wg.has(g)));
    }
    cands.sort((a, b) => b.composite - a.composite);
    const pins = new Set(CFG.wheel_pinned_ids || []);
    if (pins.size) {
      const pinned = cands.filter((r) => pins.has(r.id));
      if (pinned.length) cands = [...pinned, ...cands.filter((r) => !pins.has(r.id))];
    }
    return cands.slice(0, CFG.wheel_top_n);
  }

  function polar(cx, cy, radius, deg) {
    const rad = toRad(deg - 90);
    return [cx + radius * Math.cos(rad), cy + radius * Math.sin(rad)];
  }

  function shortLabel(name, max = 10) {
    const s = name.trim();
    return [...s].length <= max ? s : [...s].slice(0, max - 1).join("") + "…";
  }

  function drawWheel(st) {
    if (spinning) return;
    const items = wheelCandidates(st);
    const sig = items.map((r) => `${r.id}:${r.composite.toFixed(2)}`).join("|");
    if (sig === wheelSig) return; // unchanged → keep the last result on screen
    wheelSig = sig;
    wheelItems = items;
    const n = wheelItems.length;
    const rotor = $("#wheel-rotor");
    $("#wheel-spin").disabled = n === 0;
    $("#wheel-caption").textContent = n
      ? `候選名單：營業中（含未知）· 正餐為主 · 綜合分 Top ${n}${st.groups.length ? " · 分類篩選已套用" : ""}`
      : "沒有符合條件的餐廳可放入轉盤，請放寬篩選條件。";
    const pins = new Set(CFG.wheel_pinned_ids || []);
    $("#wheel-legend").innerHTML = wheelItems.map((r, i) => `
      <li data-index="${i}"><span class="wheel-no">${i + 1}</span>${pins.has(r.id) ? '<span class="wheel-pin" title="站長推薦">★</span>' : ""}
      <span class="wheel-name" title="${esc(r.name)}">${esc(shortLabel(r.name))}</span>
      <span class="wheel-meta">${r.composite.toFixed(2)}</span></li>`).join("");
    if (!n) { rotor.innerHTML = ""; resetResult(); return; }
    const cx = 200, cy = 200, R = 190, slice = 360 / n, large = slice > 180 ? 1 : 0;
    let svg = "";
    for (let i = 0; i < n; i++) {
      const center = i * slice;
      const color = WHEEL_COLORS[i % WHEEL_COLORS.length];
      if (n === 1) {
        svg += `<circle cx="${cx}" cy="${cy}" r="${R}" fill="${color}"/>`;
      } else {
        const [x1, y1] = polar(cx, cy, R, center - slice / 2);
        const [x2, y2] = polar(cx, cy, R, center + slice / 2);
        svg += `<path d="M${cx},${cy} L${x1.toFixed(2)},${y1.toFixed(2)} A${R},${R} 0 ${large},1 ${x2.toFixed(2)},${y2.toFixed(2)} Z" fill="${color}"/>`;
      }
      const [tx, ty] = polar(cx, cy, R * (n > 24 ? 0.84 : 0.62), center);
      const fs = n > 32 ? 12 : n > 24 ? 14 : 18;
      svg += `<text x="${tx.toFixed(2)}" y="${ty.toFixed(2)}" text-anchor="middle" dominant-baseline="middle" class="wheel-label" font-size="${fs}">${i + 1}</text>`;
    }
    rotor.innerHTML = svg;
    resetWheel();
  }

  const rotMod = (r) => ((r % 360) + 360) % 360;

  function segmentAt(rot, n) {
    const slice = 360 / n;
    return ((Math.floor((360 - rotMod(rot) + slice / 2) / slice) % n) + n) % n;
  }

  function resetResult() {
    $("#wheel-result").innerHTML = "<p>按下「開始轉盤」，讓命運決定午餐／晚餐。</p>";
    document.querySelectorAll("#wheel-legend li").forEach((li) => li.classList.remove("active"));
  }

  function resetWheel() {
    const rotor = $("#wheel-rotor");
    rotation = 0;
    rotor.style.transition = "none";
    rotor.style.transform = "rotate(0deg)";
    requestAnimationFrame(() => { rotor.style.transition = ""; });
    resetResult();
  }

  function spin() {
    const n = wheelItems.length;
    if (spinning || !n) return;
    spinning = true;
    $("#wheel-spin").disabled = true;
    $("#wheel-result").innerHTML = "<p>轉盤旋轉中…</p>";
    const slice = 360 / n;
    const winner = Math.floor(Math.random() * n);
    const extra = 4 + Math.floor(Math.random() * 3);
    let delta = rotMod(360 - winner * slice) - rotMod(rotation);
    if (delta <= 0) delta += 360;
    rotation += extra * 360 + delta;
    $("#wheel-rotor").style.transform = `rotate(${rotation}deg)`;
    setTimeout(() => {
      const idx = segmentAt(rotation, n);
      const r = wheelItems[idx];
      document.querySelectorAll("#wheel-legend li").forEach((li) => li.classList.toggle("active", Number(li.dataset.index) === idx));
      $("#wheel-result").innerHTML = `
        <h4>#${idx + 1} ${esc(r.name)}</h4>
        <p>綜合分數 <strong>${r.composite.toFixed(2)}</strong>　黃氏 <strong>${r.huang.toFixed(2)}</strong>　距離 <strong>${r.distText}</strong></p>
        <a class="btn btn-primary btn-big" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">📖 開啟 Google Maps</a>`;
      $("#wheel-result").scrollIntoView({ behavior: "smooth", block: "nearest" });
      spinning = false;
      $("#wheel-spin").disabled = false;
    }, 4300);
  }

  // ---------- render ----------
  let renderQueued = false;
  function render({ fit = false } = {}) {
    const st = readState();
    if (!Number.isFinite(st.lat) || !Number.isFinite(st.lon)) return;
    rows = rank(st);
    if (selectedId && !rows.some((r) => r.id === selectedId)) selectedId = null;
    $("#o-radius").textContent = st.radius.toFixed(1);
    $("#o-limit").textContent = st.limit;
    $("#result-count").textContent = `符合條件 ${rows.length} 家（半徑 ${st.radius.toFixed(1)} km）`;
    drawTable();
    drawFocus();
    drawMap(st, fit);
    drawWheel(st);
    saveState(st);
  }
  function scheduleRender(opts) {
    if (renderQueued) return;
    renderQueued = true;
    requestAnimationFrame(() => { renderQueued = false; render(opts); });
  }

  function setCenter(lat, lon, msg) {
    $("#f-lat").value = lat.toFixed(6);
    $("#f-lon").value = lon.toFixed(6);
    $("#center-status").textContent = msg || "";
    render({ fit: true });
  }

  // ---------- persistence (per-viewer convenience only) ----------
  const STORE_KEY = () => `foodmap:${CFG.counter_namespace || CFG.school}:filters`;
  function saveState(st) {
    try {
      localStorage.setItem(STORE_KEY(), JSON.stringify({
        radius: st.radius, minReviews: st.minReviews, groups: [...selectedGroups], other: $("#f-other").checked,
        budget: $("#f-budget").checked, maxSpend: $("#f-max-spend").value, unknown: st.includeUnknown,
        openOnly: st.openOnly, sort: st.sort, limit: st.limit,
      }));
    } catch (_e) { /* storage unavailable */ }
  }
  function loadState() {
    try { return JSON.parse(localStorage.getItem(STORE_KEY()) || "null"); } catch (_e) { return null; }
  }

  // ---------- UI wiring ----------
  function buildGroupChips() {
    $("#group-chips").innerHTML = CFG.food_group_sidebar.map(([label, groups]) => `
      <div class="chip-group"><h4>${esc(label)}</h4><div class="chips">
        ${groups.map((g) => `<button type="button" class="chip" data-group="${esc(g)}" aria-pressed="${selectedGroups.has(g)}">${esc(g.replace(/類$/, ""))}</button>`).join("")}
      </div></div>`).join("");
    $("#group-chips").addEventListener("click", (e) => {
      const chip = e.target.closest(".chip");
      if (!chip) return;
      const g = chip.dataset.group;
      if (selectedGroups.has(g)) selectedGroups.delete(g); else selectedGroups.add(g);
      chip.setAttribute("aria-pressed", String(selectedGroups.has(g)));
      render();
    });
  }

  function syncBudgetVisibility() {
    document.querySelectorAll(".budget-only").forEach((el) => { el.hidden = !$("#f-budget").checked; });
  }

  function setDrawer(open) {
    $("#filters").classList.toggle("open", open);
    $("#scrim").hidden = !open;
    $("#filter-toggle").setAttribute("aria-expanded", String(open));
  }

  function selectTab(name) {
    for (const t of ["map", "wheel", "guide"]) {
      $(`#tab-${t}`).setAttribute("aria-selected", String(t === name));
      $(`#panel-${t}`).hidden = t !== name;
    }
    if (name === "map") map.invalidateSize();
  }

  async function geocode() {
    const q = $("#f-place").value.trim();
    if (!q) return;
    const btn = $("#btn-geocode");
    btn.disabled = true;
    $("#center-status").textContent = "查詢中…";
    try {
      const url = `https://nominatim.openstreetmap.org/search?${new URLSearchParams({ q, format: "json", limit: "1", countrycodes: "tw", "accept-language": "zh-TW" })}`;
      const res = await fetch(url, { headers: { Accept: "application/json" } });
      const data = await res.json();
      if (!Array.isArray(data) || !data.length) throw new Error("not found");
      setCenter(Number(data[0].lat), Number(data[0].lon), `已設定：${q}`);
    } catch (_e) {
      $("#center-status").textContent = "找不到地點，請換關鍵字（可加縣市名）。";
    } finally {
      btn.disabled = false;
    }
  }

  function locate() {
    if (!navigator.geolocation) { $("#center-status").textContent = "此瀏覽器不支援定位。"; return; }
    $("#center-status").textContent = "定位中…";
    navigator.geolocation.getCurrentPosition(
      (pos) => setCenter(pos.coords.latitude, pos.coords.longitude, "已改用你目前的位置"),
      () => { $("#center-status").textContent = "無法取得位置（可能未授權）。"; },
      { enableHighAccuracy: true, timeout: 10000 },
    );
  }

  function wire() {
    ["#f-radius", "#f-limit"].forEach((s) => $(s).addEventListener("input", () => scheduleRender()));
    $("#f-radius").addEventListener("change", () => render({ fit: true }));
    ["#f-min-reviews", "#f-max-spend", "#f-sort", "#f-other", "#f-unknown-price", "#f-open-only"].forEach((s) => $(s).addEventListener("change", () => {
      if (s === "#f-sort") tableSort = null;
      render();
    }));
    $("#f-search").addEventListener("input", () => scheduleRender());
    $("#f-budget").addEventListener("change", () => { syncBudgetVisibility(); render(); });
    ["#f-lat", "#f-lon"].forEach((s) => $(s).addEventListener("change", () => render({ fit: true })));
    $("#btn-clear-groups").addEventListener("click", () => {
      selectedGroups.clear();
      $("#f-other").checked = false;
      document.querySelectorAll(".chip").forEach((c) => c.setAttribute("aria-pressed", "false"));
      render();
    });
    $("#btn-geocode").addEventListener("click", geocode);
    $("#f-place").addEventListener("keydown", (e) => { if (e.key === "Enter") geocode(); });
    $("#btn-locate").addEventListener("click", locate);
    $("#btn-reset-center").addEventListener("click", () => setCenter(CFG.center[0], CFG.center[1], `已回到${CFG.campus_name}`));

    $("#rtable tbody").addEventListener("click", (e) => {
      if (e.target.closest("a")) return;
      const tr = e.target.closest("tr[data-id]");
      if (!tr) return;
      selectRow(tr.dataset.id);
      if (window.matchMedia("(max-width: 1199px)").matches) $("#map").scrollIntoView({ behavior: "smooth", block: "start" });
    });
    $("#rtable thead").addEventListener("click", (e) => {
      const th = e.target.closest("th[data-sort]");
      if (!th) return;
      const key = th.dataset.sort;
      const defaultDir = key === "name" || key === "distance" ? 1 : -1;
      tableSort = tableSort && tableSort.key === key ? (tableSort.dir === defaultDir ? { key, dir: -defaultDir } : null) : { key, dir: defaultDir };
      drawTable();
    });

    $("#tab-map").addEventListener("click", () => selectTab("map"));
    $("#tab-wheel").addEventListener("click", () => selectTab("wheel"));
    $("#tab-guide").addEventListener("click", () => selectTab("guide"));
    $("#wheel-spin").addEventListener("click", spin);
    $("#wheel-reset").addEventListener("click", () => { if (!spinning) resetWheel(); });

    $("#filter-toggle").addEventListener("click", () => setDrawer(true));
    $("#filters-close").addEventListener("click", () => setDrawer(false));
    $("#filters-done").addEventListener("click", () => setDrawer(false));
    $("#scrim").addEventListener("click", () => setDrawer(false));
    document.addEventListener("keydown", (e) => { if (e.key === "Escape") setDrawer(false); });
  }

  function visitCounter() {
    const ns = CFG.counter_namespace;
    const label = $("#visits");
    if (!ns) { label.remove(); return; }
    const base = `https://api.counterapi.dev/v1/${encodeURIComponent(ns)}/visits/`;
    let counted = false;
    const key = `${ns}_visit_counted`;
    try { counted = sessionStorage.getItem(key) === "1"; } catch (_e) { /* ignore */ }
    fetch(counted ? base : `${base}up`)
      .then((r) => { if (!r.ok) throw new Error(); return r.json(); })
      .then((p) => {
        const v = Number(p && p.count);
        if (!Number.isFinite(v) || v < 0) throw new Error();
        try { sessionStorage.setItem(key, "1"); } catch (_e) { /* ignore */ }
        label.textContent = `累計瀏覽 ${v.toLocaleString("zh-TW")} 人次`;
      })
      .catch(() => { label.textContent = "瀏覽人次統計暫不可用"; });
  }

  async function boot() {
    try {
      const [cfg, places] = await Promise.all([
        fetch("data/config.json").then((r) => r.json()),
        fetch("data/places.json").then((r) => r.json()),
      ]);
      CFG = cfg;
      PLACES = places;
    } catch (_e) {
      $("#site-subtitle").textContent = "資料載入失敗，請重新整理。";
      return;
    }
    document.title = CFG.title;
    $("#site-title").textContent = CFG.title;
    $("#site-subtitle").textContent = `中心點預設：${CFG.campus_name}（${CFG.center[0]}, ${CFG.center[1]}）· 共 ${PLACES.length} 家 · 綜合分 = 黃氏星等 × 距離衰減`;
    $("#author").textContent = CFG.author_notice;
    if (CFG.repo_url) $("#repo-link").innerHTML = ` · <a href="${esc(CFG.repo_url)}" target="_blank" rel="noopener noreferrer">GitHub</a>`;

    const saved = loadState();
    $("#f-lat").value = CFG.center[0].toFixed(6);
    $("#f-lon").value = CFG.center[1].toFixed(6);
    if (CFG.max_radius_km) $("#f-radius").max = CFG.max_radius_km;
    $("#f-radius").value = Math.min(saved?.radius ?? CFG.default_radius_km, Number($("#f-radius").max));
    if (saved) {
      $("#f-min-reviews").value = saved.minReviews ?? 0;
      (saved.groups || []).forEach((g) => selectedGroups.add(g));
      $("#f-other").checked = !!saved.other;
      $("#f-budget").checked = !!saved.budget;
      $("#f-max-spend").value = saved.maxSpend ?? 100;
      $("#f-unknown-price").checked = saved.unknown ?? true;
      $("#f-open-only").checked = !!saved.openOnly;
      if (SORTERS[saved.sort]) $("#f-sort").value = saved.sort;
      $("#f-limit").value = saved.limit ?? 300;
    }
    syncBudgetVisibility();
    buildGroupChips();
    initMap();
    wire();
    render({ fit: true });
    visitCounter();
    // Re-evaluate open/closed status every 5 minutes for long-open tabs.
    setInterval(() => { if (!spinning) render(); }, 5 * 60 * 1000);
  }

  boot();
})();
